-- Triggers `users`
--
DELIMITER $$
CREATE TRIGGER `before_user_insert` BEFORE INSERT ON `users` FOR EACH ROW BEGIN
    -- 1. Set the default user role if not explicitly provided
    IF NEW.user_role IS NULL THEN
        SET NEW.user_role = 'CUSTOMER';
    END IF;

    -- 2. Generate referral code ONLY if the final role is CUSTOMER and the code is NULL
    IF NEW.user_role = 'CUSTOMER' AND NEW.referral_code IS NULL THEN
        -- Call the stored function to get a unique code
        SET NEW.referral_code = generate_referral_code();
    END IF;
END
$$
DELIMITER ;

