DELIMITER $$
--
-- Events
--
CREATE DEFINER=`root`@`localhost` EVENT `update_best_sellers` ON SCHEDULE EVERY 1 DAY STARTS '2025-10-26 03:00:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- Step 1: Reset the 'is_best_seller' flag for ALL products
    UPDATE products
    SET is_best_seller = FALSE;

    -- Step 2: Identify the top 10 products with the highest quantity sold in COMPLETED orders
    -- and set their 'is_best_seller' flag to TRUE.
    UPDATE products p
    INNER JOIN (
        SELECT
            oi.product_id,
            SUM(oi.quantity) AS total_sold
        FROM
            orders o
        JOIN
            order_items oi ON o.order_id = oi.order_id
        WHERE
            o.order_status = 'completed'
            -- Optional: Add a time window (e.g., last 30 days) for more relevant 'Best Seller' data
            AND o.order_date >= DATE_SUB(NOW(), INTERVAL 30 DAY)
        GROUP BY
            oi.product_id
        ORDER BY
            total_sold DESC
        LIMIT 10
    ) AS top_selling_products ON p.product_id = top_selling_products.product_id
    SET p.is_best_seller = TRUE;

END$$

CREATE DEFINER=`root`@`localhost` EVENT `update_popular_products` ON SCHEDULE EVERY 1 DAY STARTS '2025-10-26 03:10:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- Step 1: Reset the 'is_popular' flag for ALL products
    UPDATE products
    SET is_popular = FALSE;

    -- Step 2: Identify the top 10 products with the highest quantity in all active carts
    -- and set their 'is_popular' flag to TRUE.
    UPDATE products p
    INNER JOIN (
        SELECT
            ci.product_id,
            SUM(ci.quantity) AS total_in_carts
        FROM
            cart_items ci
        GROUP BY
            ci.product_id
        ORDER BY
            total_in_carts DESC
        LIMIT 10
    ) AS top_cart_products ON p.product_id = top_cart_products.product_id
    SET p.is_popular = TRUE;

END$$

CREATE DEFINER=`root`@`localhost` EVENT `check_high_risk_buyers` ON SCHEDULE EVERY 1 DAY STARTS '2025-11-11 02:00:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- Update the status of users who have 3 or more active warnings
    UPDATE users u
    INNER JOIN (
        -- Subquery to find user_ids with 3 or more active warnings
        SELECT
            user_id,
            COUNT(warning_id) AS total_warnings
        FROM
            buyer_warnings
        WHERE
            is_active = TRUE -- Only count warnings that haven't been resolved/lifted
        GROUP BY
            user_id
        HAVING
            total_warnings >= 3 -- The threshold is 3 or more
    ) AS high_risk ON u.id = high_risk.user_id
    
    -- Only update accounts that are currently 'active'
    SET u.account_status = 'inactive'
    WHERE u.user_role = 'CUSTOMER' 
      AND u.account_status = 'active'; 

    -- Optional: Insert a notification for the suspended user
    SELECT
        u.id,
        'ACCOUNT_STATUS',
        CONCAT('ALERT: Your account has been suspended due to ', high_risk.total_warnings, ' buyer warnings (e.g., No-Show, Bogus Buyer).')
    FROM users u
    INNER JOIN high_risk ON u.id = high_risk.user_id
    -- Only notify if the status was just changed (or if a flag is used to prevent duplicate notifications)
    WHERE u.account_status = 'inactive'; 

END$$

